"""Rebuild the public delivery report from local evidence; never invent trial rows."""
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parents[2]

def build():
    saved=json.loads((ROOT/'forge/results/snapshot.json').read_text())
    ledger=json.loads((ROOT/'forge/local-results/budget.json').read_text())
    notebooks=json.loads((ROOT/'forge/publication-manifest.json').read_text())['notebooks']
    apps=json.loads((ROOT/'forge/local-results/app-checks.json').read_text())
    validation=json.loads((ROOT/'forge/local-results/notebook-validation.json').read_text())
    rows=saved['trials']
    published=sum(row['status']=='published_verified' for row in notebooks)
    delivery={'schemaVersion':1,'status':'blocked_on_usage_and_hosted_publication','upstreamCommit':'a9342ff471f2c0e60be0c08b9f4a7c502df4e442','forkUrl':'https://github.com/ash0ts/learn-harness-engineering','targetRepeatsPerVariant':3,'trialAttempts':len(rows),'passedTrials':sum(row['outcome']=='passed' for row in rows),'completedComparisonBlocks':0,'realTwoHourExerciseCompleted':False,'qualifications':{'attempted':len(saved['qualifications']),'passed':sum(row['passed'] for row in saved['qualifications'])},'budget':ledger,'checks':{'offlineAppsPassed':sum(a['passed'] for a in apps),'offlineAppsTotal':len(apps),'notebooksRenderedLocally':sum(n['rendered'] for n in validation['notebooks']),'notebooksPublishedVerified':published},'prs':[f'https://github.com/ash0ts/learn-harness-engineering/pull/{n}' for n in [1,2,3,5,6,7,8]],'notebooks':notebooks,'trials':rows}
    (ROOT/'forge/results/delivery.json').write_text(json.dumps(delivery,indent=2)+'\n')
    lines=['# Forge track delivery and evidence', '', '**Status: implementation is in dependent draft PRs; the live study and hosted notebook publication are incomplete.**', '', 'The frozen upstream revision is `'+delivery['upstreamCommit']+'`. The [public personal fork]('+delivery['forkUrl']+') preserves the original offline course. Results belong to the private `wandb/learn-harness-engineering-forge` project. No PR has been merged.', '', '## What ran', '', '| Evidence | Actual completion |','| --- | --- |',f"| Offline application checks | {sum(a['passed'] for a in apps)}/{len(apps)} app copies pass existing type, build, test and available architecture checks |", '| Forge integration tests | 27 pass, including accelerated timer, graph approval/rollback and shared sandbox slots |','| Documentation | VitePress build and English anchor validation pass |',f"| Canonical notebooks | {len(validation['notebooks'])}/9 validate and render locally without credentials |",f"| Qualification | {sum(row['passed'] for row in saved['qualifications'])}/{len(saved['qualifications'])} marked passed; successful record predates protocol revision 2 |",f'| Coding trials | {len(rows)} attempted; 0 passing, 0 complete comparison blocks |','| Real two-hour exercise | Started, then halted during its first trial; not completed |','| Live graph exercise | Not launched |',f'| Hosted notebooks | {len(notebooks)} BASIC records created; {published}/9 canonical sources uploaded and verified |','', 'The one coding attempt was a timer trial. Its original outcome remains `telemetry_missing`. An audit found that all eight submitted calls returned usage; a ninth attempt was refused locally by the input bound. Its billing estimate was reconciled, but the failed attempt was not relabeled as a successful trial. Later fixes corrected the virtual Pi working directory, excluded macOS tar metadata and counted only submitted inference requests. The latest qualification under the revised protocol timed out with one submitted inference and no returned token usage. That unresolved attempt halted paid launches.', '', '## Budget', '', f"Known/audited estimated spend: **${ledger['spentEstimateUsd']:.6f}**. Unresolved reservations: **${sum(ledger['reservations'].values()):.2f}**. Original application budget: **${ledger['limitUsd']:.2f}**. These are estimates, not an invoice or guaranteed billing cap.", '', 'The unresolved $2 qualification reservation is retained. The provider billing query has returned no course-project rows, including previously observed calls; this cannot be interpreted as zero spend. No paid launch, notebook EDIT session or inference was started after this halt. Creating/renaming BASIC notebook records did not launch notebook compute. Notebook execution pricing remains unset until a runtime resource/rate check can support a reservation.', '', 'The ledger and its audit trail are included in `delivery.json`. It must not be reset to resume. Resume only after usage reconciliation or an explicitly recorded user exception, then qualify the frozen protocol again before comparisons.', '', '## Evidence links', '']
    for row in rows:
        lines += [f"- [W&B timer trial]({row['wandbRunUrl']}) · [versioned trial artifact]({row['artifactUrl']})"]
        lines += [f"- [Agent Lens coding conversation](https://forge.coreweave.com/agent-lens/wandb/learn-harness-engineering-forge/conversations/{cid})" for cid in row['conversationIds']]
    receipt_path=ROOT/'forge/results/evidence-publication.json'
    if receipt_path.exists():
        receipt=json.loads(receipt_path.read_text())
        lines += [f"- [Qualification audit run]({receipt['runUrl']}) · [qualification evidence and exact source archives]({receipt['artifactUrl']})"]
    lines += ['', 'Agent Lens was inspected in the authenticated UI. The coding conversation contains nested model and tool activity. Separate application conversations show four turns (import, indexing, two Q&A calls) and twelve spans. Concurrency isolation is implemented with `runIsolated()`; a live concurrent trace qualification is still outstanding. The unsuccessful inference conversation is retained with its error.', '', '## Hosted notebook records', '', '**These links currently open BASIC placeholders, not the canonical course notebooks.** The manifest records their stable IDs, intended source revisions/checksums and original committed BASIC versions. No publication success is claimed.', '', '| Notebook | Remote record | Status |','| --- | --- |']
    for n in notebooks: lines.append(f"| {Path(n['file']).name} | [{n['title']}]({n['url']}) | {n['status']} |")
    lines += ['', '## Reproduce and resume', '', 'From this checkout:', '', '```sh','npm ci --prefix forge','npm run build --prefix forge','npm run check --prefix forge','npm test --prefix forge','python3 forge/scripts/check_apps.py','npm ci','npm run anchors:check','npm run docs:build','npm run forge --prefix forge -- validate-notebooks','python3 forge/scripts/report.py','```', '', 'The coordinator uses the existing `forge/local-results/budget.json`. Supply credentials externally. After reconciliation, run `doctor --qualify --execute`, then schedule complete comparison blocks with `compare --repeats 3 --execute`. The loop and graph commands are documented in Projects 07 and 08. An ambiguous pending checkpoint requires review rather than an automatic replay.', '', 'For publication, run `uv run --script forge/scripts/publication.py check-remote NOTEBOOK.py` before opening EDIT. Reserve notebook compute from the same ledger, then load canonical source through the authenticated Marimo editor and use its normal save workflow. Run `verify NOTEBOOK.py` afterward. It checks committed `currentVersion`, source SHA-256, fresh rendered output, absence of cell errors and an idle launch control. It will reject the current BASIC placeholders. Reuse manifest IDs; do not create replacements to bypass remote-edit detection.', '', '## Limits of the evidence', '', '- No treatment-effect conclusion is supported: there are no complete comparison blocks and no successful coding trial.', '- Offline build/test success is distinct from the protected service and Electron checks. The seeded Project 04 empty-chunk defect is detected; the original sandboxed preload also fails the Electron bridge check. Those exercise gaps remain for the learner/agent to fix.', '- Generation settings and model are frozen in `forge/protocol.json`; a changed protocol needs qualification. The model was listed and successfully called during earlier qualification, but the most recent request timed out.', '- The actual two-hour timer, live graph retries/rollback/approval, and concurrent trace isolation remain unqualified. Unit tests do not replace those live exercises.', '- Hosted notebooks need a mounted shared coordinator checkout for paid reruns. Analysis is self-contained; a hosted runtime without that checkout cannot execute reruns.', '- Hosted notebook source commit and rendered output remain unverified. BASIC version checksums intentionally differ from canonical sources.', '- Human-intervention time and time saved were not measured. No model training was performed.', '']
    (ROOT/'forge/results/README.md').write_text('\n'.join(lines))
    print('Report rebuilt from recorded evidence')

if __name__=='__main__':build()
